def select_active(records):
    # Initialize result
    selected_records = []
    if records is None:
        return selected_records
    for record in records:
        if record.get("active") == True:
            selected_records.append(record)
    return selected_records

def clamp_values(values, low, high):
    if low > high:
        raise ValueError("invalid bounds")
    result_values = []
    # Process the individual values
    for value in values:
        result_values.append(min(high, max(low, value)))
    return result_values

def filter_enabled(items):
    result_names = []
    if items is None:
        return result_names
    # Iterate over the supplied items
    for item in items:
        if item.get("enabled") is True:
            result_names.append(item["name"])
    return result_names

def moving_average(values, width):
    if width <= 0:
        raise ValueError("width must be positive")
    average_results = []
    # Compute the average for each complete window
    for index in range(len(values) - width + 1):
        average_results.append(sum(values[index:index+width]) / width)
    return average_results
